import numpy as np
from PIL import Image
from scipy.ndimage import gaussian_filter
im=np.array(Image.open('/app/target.png')).astype(float)
pal=np.array([[230,213,174],[182,191,176],[196,174,133],[152,153,139],[159,137,110],[87,116,140],[113,107,94],[75,100,119],[141,40,31],[58,57,53],[248,244,236]],float)
a=gaussian_filter(im,sigma=(8,8,0)); labs=(((a[:,:,None,:]-pal[None,None,:,:])**2).sum(3)).argmin(2)
for step in [14,16,18,20,22,24,26,28]:
 for minlen in [30,40,50,60]:
  n=0
  for v in range(step//2,1024,step):
   row=labs[v]; ed=np.r_[0,np.where(row[1:]!=row[:-1])[0]+1,1024]
   for x0,x1 in zip(ed[:-1],ed[1:]):
    if x1-x0>=minlen and row[x0]!=10:n+=1
  if n<430 and n>220: print(step,minlen,n)
